               // Query para buscar o total da base B050

$sql = "SELECT coalesce(sum(g.r14_valor), 0) as total 
      FROM gerfsal g
      INNER JOIN basesr b ON g.r14_rubric = b.r09_rubric 
          AND g.r14_anousu = b.r09_anousu 
          AND g.r14_mesusu = b.r09_mesusu 
          AND g.r14_instit = b.r09_instit 
      WHERE g.r14_regist = " . db_sqlformat($registro) . "
        AND g.r14_anousu = " . db_sqlformat($anousu) . "
        AND g.r14_mesusu = " . db_sqlformat($mesusu) . "
        AND g.r14_instit = " . db_sqlformat($DB_instit) . "
        AND b.r09_base = 'B050'";

//die($sql);
$result = db_query($sql);

// Verifique se a query foi executada com sucesso
if (!$result) {
    echo "Erro na execução da query: " . pg_last_error();
    return;
}

// Verifique se a query retornou resultados
if (pg_num_rows($result) == 0) {
    echo "Nenhum resultado encontrado para a query.";
    return;
}

$valor_base = pg_fetch_result($result, 0, 0);

if ($valor_base > 0) {
    //$tot_vpass += ($valor_base * 0.06 / 30 * $quantvale);
    $tot_vpass += ($valor_base * 0.06 / 30);
} else {
    // Mantém o cálculo original caso não encontre valor
    $tot_vpass += ($quantvale * $vtfempr[0]["r16_valor"]);
}

